import numpy as np
from scipy.optimize import minimize
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
L=np.log(P); one=np.ones_like(t)
core=[P*L,P,P*P,t,one]
def sc(p, mode):
    w,k=p[0],p[1]
    if mode==0:
        g=[one/P,t/P,np.sin(w*t)/P,np.cos(w*t)/P,np.sin(2*w*t)/P,np.cos(2*w*t)/P]
    elif mode==1:
        g=[one/P,t/P,t*np.exp(-k*t)/P,np.sin(w*t)/P,np.cos(w*t)/P]
    elif mode==2:
        g=[one/P,t/P,np.exp(-k*t)/P,np.sin(w*t)/P,np.cos(w*t)/P]
    else:
        g=[one/P,t/P,t*t/P,np.sin(w*t)/P,np.cos(w*t)/P]
    X=np.column_stack(g+core)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return np.mean((y-X@c)**2)/np.var(y)
